-- Continues publication.sql's isolated transaction. No user data is used or retained.
select pg_temp.pu_assert((select count(*) from public.published_player_games)=22,'only confirmed participants projected');
create temporary table player_games_before as select * from public.published_player_games;
create temporary table player_stats_before as select snapshot from public.published_statistics where dispute_id=pg_temp.pu_id(3);
update public.persons set name='Nome privado atual' where id=pg_temp.pu_id(201);
update public.teams set name='Equipe privada atual' where id=pg_temp.pu_id(4);
select pg_temp.pu_assert((select jsonb_agg(snapshot order by person_id,game_id) from public.published_player_games)=(select jsonb_agg(snapshot order by person_id,game_id) from player_games_before),'live cadastre does not change public participation');
update public.admin_access set enabled=true where user_id=pg_temp.pu_id(98);
create temporary table player_game_intent as select jsonb_build_object('requestId',pg_temp.pu_id(94000),'gameId',pg_temp.pu_id(8),'gameVersion',(select version from public.games where id=pg_temp.pu_id(8)),'basePublicationVersion',2,'source',jsonb_build_object('kind','sheet','baseSheetVersion',(select version from public.game_sheets where game_id=pg_temp.pu_id(8)),'document',jsonb_set((select document from public.game_sheets where game_id=pg_temp.pu_id(8)),'{events,0,code}','"2"')),'reason','Revisão das participações confirmadas.','fallback',false) as payload;
grant select on player_game_intent to authenticated;
create function pg_temp.player_projection_fail() returns trigger language plpgsql as $$begin raise exception 'synthetic player projection failure';end$$;
create trigger player_projection_fixture before insert on public.published_player_games for each row execute function pg_temp.player_projection_fail();
set local role authenticated;
select pg_temp.pu_error('select public.publish_sheet_game((select payload from player_game_intent))','P0001');
reset role;
select pg_temp.pu_assert(public.get_public_game(pg_temp.pu_id(8))->'version'='2','projection failure rolls back game publication');
select pg_temp.pu_assert((select snapshot=public.get_public_statistics_source(pg_temp.pu_id(3)) from player_stats_before),'projection failure rolls back statistics source');
select pg_temp.pu_assert((select jsonb_agg(snapshot order by person_id,game_id) from public.published_player_games)=(select jsonb_agg(snapshot order by person_id,game_id) from player_games_before),'projection failure preserves old player facts');
select pg_temp.pu_assert(not exists(select 1 from private.game_publication_commands where request_id=pg_temp.pu_id(94000)),'projection failure leaves no receipt');
drop trigger player_projection_fixture on public.published_player_games;
set local role authenticated;
select pg_temp.pu_assert(public.publish_sheet_game((select payload from player_game_intent))->'version'='3','same frozen command succeeds after rollback');
select pg_temp.pu_assert(public.publish_sheet_game((select payload from player_game_intent))->'version'='3','replay returns original ACK');
select pg_temp.pu_error('delete from public.published_player_games','42501');
select pg_temp.pu_error('select private.refresh_player_game(pg_temp.pu_id(8))','42501');
set local role anon;
select pg_temp.pu_assert((select count(*) from public.published_player_games)=22,'anonymous only reads public projections');
select pg_temp.pu_error('insert into public.published_player_games select * from public.published_player_games','42501');
select pg_temp.pu_error('update public.published_player_games set publication_version=4','42501');
reset role;
select pg_temp.pu_assert((select count(*) from public.published_player_games where game_id=pg_temp.pu_id(8))=11,'correction replaces rather than duplicates participant rows');
select pg_temp.pu_assert((select bool_and(snapshot#>>'{fact,phase}' is null) from public.published_player_games),'private regulation is not inferred as phase');
select pg_temp.pu_assert(exists(select 1 from public.published_player_games p join private.game_publication_entries e on e.person_id=p.person_id and e.game_id=p.game_id and e.version=p.publication_version where p.snapshot#>>'{fact,jersey}'='00'),'zero-zero jersey preserves immutable identity lineage');
select pg_temp.pu_assert((select snapshot#>>'{facts,teams,home,points}' from private.game_publication_versions where game_id=pg_temp.pu_id(8) and version=2)='3','prior public result remains immutable');
select pg_temp.pu_assert((select relrowsecurity from pg_class where oid='public.published_player_games'::regclass),'projection has RLS');
set local role service_role;
select pg_temp.pu_error('delete from public.published_player_games','42501');
reset role;
-- Owner removal is covered defensively; there is no application unpublish command here.
delete from public.published_games where game_id=pg_temp.pu_id(9);
select pg_temp.pu_assert(not exists(select 1 from public.published_player_games where game_id=pg_temp.pu_id(9)),'removed current projection leaves no stale profile participation');
rollback;
